        int sc_error;
        char *description;
 };

 static const struct coolkey_error_codes_st coolkey_error_codes[]= {
        {SC_ERROR_UNKNOWN,                       "Reserved 0x9c00" },
        {SC_ERROR_NOT_ENOUGH_MEMORY,             "No memory left on card" },
